'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),os=require('node:os'),crypto=require('node:crypto'),{execFileSync}=require('node:child_process');
test('native staging copies exact current recording entry and dependency bytes',()=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'nova-assets-test-'));try{execFileSync('python3',[path.join(__dirname,'../scripts/music-stage-native-web.py'),root]);const manifest=JSON.parse(fs.readFileSync(path.join(root,'asset-manifest.json')));assert.ok(manifest.files.some(f=>f.path==='music-studio.js'));assert.ok(manifest.files.some(f=>f.path==='music-studio-midi-input.js'));for(const f of manifest.files){const bytes=fs.readFileSync(path.join(root,f.path));assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),f.sha256);assert.deepEqual(bytes,fs.readFileSync(path.join(__dirname,'..',f.path)))}const html=fs.readFileSync(path.join(root,'music-studio.html'),'utf8');for(const m of html.matchAll(/(?:src|href)="\.\/([^"?]+)/g))assert.ok(fs.existsSync(path.join(root,m[1])),m[1]);}finally{fs.rmSync(root,{recursive:true,force:true})}});
test('Xcode both production targets stage assets and file loading is explicit',()=>{const project=fs.readFileSync(path.join(__dirname,'../tools/music-native-wrapper/MusicStudioNative.xcodeproj/project.pbxproj'),'utf8');assert.equal((project.match(/C30000000000000000000001\); buildRules/g)||[]).length,2);assert.match(project,/music-stage-native-web.py/);const host=fs.readFileSync(path.join(__dirname,'../tools/music-native-wrapper/MusicStudioWebViewHost.swift'),'utf8');assert.match(host,/loadFileURL\(configuration.startURL, allowingReadAccessTo:/)});
